method below_zero(operations: seq<int>) returns (result: bool)
    requires operations != null
    ensures result == (exists i :: 0 <= i < |operations| && (sum(operations[0..i+1]) < 0))
{
    var balance := 0;
    result := false;

    var i := 0;
    while i < |operations|
        invariant 0 <= i <= |operations|
        invariant balance == sum(operations[0..i])
        invariant result == (exists j :: 0 <= j < i && (sum(operations[0..j+1]) < 0))
    {
        balance := balance + operations[i];
        if balance < 0 {
            result := true;
        }
        i := i + 1;
    }
}
```

